import test from 'node:test';
import assert from 'node:assert/strict';
import {parameters,defaults,derivative,forcedDerivative,rk4,buildAttractor,cameraAt,readSettings,settingsQuery} from './core.mjs';
test('reference equations and coefficients are exact',()=>{assert.deepEqual(parameters,{a:36,b:3,c:20});assert.deepEqual(derivative([2,3,4]),[36,52,-6]);assert.deepEqual(derivative([0,0,0]),[0,0,0]);});
test('RK4 agrees with two half steps on a short interval',()=>{const p=[3,4,20],a=rk4(p,.002),b=rk4(rk4(p,.001),.001);for(let i=0;i<3;i++)assert.ok(Math.abs(a[i]-b[i])<1e-7);});
test('deterministic trajectory is finite, bounded, occupies both wings and has real depth',()=>{const a=buildAttractor({count:12000}),b=buildAttractor({count:12000});assert.deepEqual(a.data,b.data);assert.ok(a.data.every(Number.isFinite));assert.ok(a.bounds.min[0]<-1&&a.bounds.max[0]>1);assert.ok(a.bounds.max[2]-a.bounds.min[2]>.3);assert.ok(a.bounds.max.every(n=>Math.abs(n)<2));assert.ok(a.bounds.min.every(n=>Math.abs(n)<2));assert.equal(a.data[3],0);assert.equal(a.data.at(-1),1);});
test('camera loop returns exactly, with matching endpoint velocity',()=>{assert.deepEqual(cameraAt(defaults,0),cameraAt(defaults,1));const e=1e-5,a=cameraAt(defaults,e),b=cameraAt(defaults,1-e),s=cameraAt(defaults,0);assert.ok(Math.abs((a.elevation-s.elevation)/e-(s.elevation-b.elevation)/e)<1e-7);assert.deepEqual(cameraAt({...defaults,motion:'still'},.2),cameraAt({...defaults,motion:'still'},.7));});
test('scene links preserve all controls and sanitize untrusted numbers',()=>{const p={...defaults,azimuth:25,elevation:-8,zoom:1.2,palette:'glacier'},r=readSettings(settingsQuery(p,.25));assert.deepEqual(r.parameters,p);assert.equal(r.phase,.25);assert.equal(r.paused,true);const bad=readSettings('?zoom=Infinity&duration=1&palette=bad&elevation=100&phase=no');assert.equal(bad.parameters.zoom,defaults.zoom);assert.equal(bad.parameters.duration,8);assert.equal(bad.parameters.elevation,80);assert.equal(bad.parameters.palette,'ember');assert.equal(bad.phase,0);});
test('reject invalid integration sizes and steps',()=>{for(const opts of [{count:1},{count:NaN},{dt:0},{dt:1},{burn:-1}])assert.throws(()=>buildAttractor(opts),RangeError);});

test('camera elevation remains smooth at both slider extremes',()=>{for(const elevation of [-80,-78,78,80]){const p={...defaults,elevation},e=1e-5,a=cameraAt(p,e),b=cameraAt(p,1-e),s=cameraAt(p,0);assert.ok(Math.abs((a.elevation-s.elevation)/e-(s.elevation-b.elevation)/e)<1e-7);for(let phase=0;phase<1;phase+=.01)assert.ok(Math.abs(cameraAt(p,phase).elevation)<=80*Math.PI/180+1e-12);}});

test('cyclic origin changes the vector field, not just display coordinates',()=>{const p=[2,3,4],time=1.2,A=3,w=.5;assert.deepEqual(forcedDerivative(p,time,{amplitude:A,omega:w}),derivative([p[0]-A*Math.sin(w*time),p[1],p[2]]));assert.deepEqual(forcedDerivative(p,time,{amplitude:0}),derivative(p));const a=rk4(p,.002,{time,amplitude:A}),b=rk4(rk4(p,.001,{time,amplitude:A}),.001,{time:time+.001,amplitude:A});for(let i=0;i<3;i++)assert.ok(Math.abs(a[i]-b[i])<1e-7);});
test('forced trajectory is deterministic and remains bounded across both lobes in the sampled interval',()=>{const a=buildAttractor({amplitude:3}),b=buildAttractor({amplitude:3});assert.deepEqual(a.data,b.data);assert.ok(a.data.every(Number.isFinite));assert.ok(a.bounds.min[0]<-1&&a.bounds.max[0]>1);assert.ok(a.bounds.max.every(n=>Math.abs(n)<2));assert.ok(a.bounds.min.every(n=>Math.abs(n)<2));assert.notDeepEqual(a.data,buildAttractor().data);});
test('links preserve all three forms and cyclic/fixed comparisons',()=>{for(const form of ['flow','sculpture','trace'])for(const origin of ['fixed','cyclic']){const p={...defaults,form,origin};assert.deepEqual(readSettings(settingsQuery(p,.2)).parameters,p);}for(const amplitude of [-1,6,NaN])assert.throws(()=>buildAttractor({amplitude}),RangeError);});
